using Microsoft.EntityFrameworkCore;using QuanLyKho.Data;using QuanLyKho.DTOs;using QuanLyKho.Models;namespace QuanLyKho.Services;public sealed class CategoryService{readonly ApplicationDbContext db;public CategoryService(ApplicationDbContext db)=>this.db=db;public async Task<IReadOnlyList<CategoryDto>> GetAllAsync()=>await db.Categories.AsNoTracking().OrderBy(x=>x.CategoryName).Select(x=>new CategoryDto(x.Id,x.CategoryName,x.Description,x.Products.Count)).ToListAsync();public async Task<CategoryDto> GetByIdAsync(int id)=>await db.Categories.AsNoTracking().Where(x=>x.Id==id).Select(x=>new CategoryDto(x.Id,x.CategoryName,x.Description,x.Products.Count)).FirstOrDefaultAsync()??throw new KeyNotFoundException("Không tìm thấy danh mục.");public async Task<CategoryDto> CreateAsync(CategoryRequest r){var n=r.CategoryName.Trim();if(await db.Categories.AnyAsync(x=>x.CategoryName==n))throw new InvalidOperationException("Danh mục đã tồn tại.");var e=new Category{CategoryName=n,Description=string.IsNullOrWhiteSpace(r.Description)?null:r.Description.Trim()};db.Categories.Add(e);await db.SaveChangesAsync();return new(e.Id,e.CategoryName,e.Description,0);}public async Task<CategoryDto> UpdateAsync(int id,CategoryRequest r){var e=await db.Categories.FindAsync(id)??throw new KeyNotFoundException("Không tìm thấy danh mục.");var n=r.CategoryName.Trim();if(await db.Categories.AnyAsync(x=>x.Id!=id&&x.CategoryName==n))throw new InvalidOperationException("Danh mục đã tồn tại.");e.CategoryName=n;e.Description=string.IsNullOrWhiteSpace(r.Description)?null:r.Description.Trim();await db.SaveChangesAsync();return await GetByIdAsync(id);}public async Task DeleteAsync(int id){var e=await db.Categories.Include(x=>x.Products).FirstOrDefaultAsync(x=>x.Id==id)??throw new KeyNotFoundException("Không tìm thấy danh mục.");if(e.Products.Count>0)throw new InvalidOperationException($"Không thể xóa danh mục {e.CategoryName} vì đang có sản phẩm liên kết.");db.Categories.Remove(e);await db.SaveChangesAsync();}}